import{_ as t,o as r,c as i,ak as a}from"./chunks/framework.Ca1nQs_n.js";const g=JSON.parse('{"title":"Archiver et mettre en ligne un projet Unity avec GitHub Pages","description":"","frontmatter":{},"headers":[],"relativePath":"06_MiseEnLigne.md","filePath":"06_MiseEnLigne.md","lastUpdated":1769182706000}'),s={name:"06_MiseEnLigne.md"};function o(l,e,n,u,c,d){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="archiver-et-mettre-en-ligne-un-projet-unity-avec-github-pages" tabindex="-1">Archiver et mettre en ligne un projet Unity avec GitHub Pages <a class="header-anchor" href="#archiver-et-mettre-en-ligne-un-projet-unity-avec-github-pages" aria-label="Permalink to “Archiver et mettre en ligne un projet Unity avec GitHub Pages”">​</a></h1><h2 id="etape-1-compiler-le-projet" tabindex="-1">Étape 1 : Compiler le projet <a class="header-anchor" href="#etape-1-compiler-le-projet" aria-label="Permalink to “Étape 1 : Compiler le projet”">​</a></h2><ol><li>Créez un dossier <code>docs</code> à la racine de votre dépôt GitHub si ce n&#39;est pas déjà fait. Ce dossier sera utilisé pour héberger les fichiers compilés.</li><li>Allez dans le menu <strong>File</strong> &gt; <strong>Build Profiles</strong> &gt; <strong>Build</strong></li><li>Cliquez sur <strong>Build</strong> dans la fenêtre de build.</li><li>Choisissez un dossier de destination pour les fichiers compilés.</li><li>Attendez que Unity termine le processus de compilation. Cela peut prendre quelques minutes en fonction de la taille de votre projet.</li></ol><h2 id="etape-2-preparer-les-fichiers-pour-github-pages" tabindex="-1">Étape 2 : Préparer les fichiers pour GitHub Pages <a class="header-anchor" href="#etape-2-preparer-les-fichiers-pour-github-pages" aria-label="Permalink to “Étape 2 : Préparer les fichiers pour GitHub Pages”">​</a></h2><ol><li>Une fois la compilation terminée, accédez au dossier de destination que vous avez choisi.</li><li>Vous verrez plusieurs fichiers et dossiers, y compris un dossier <code>Build</code>, un dossier <code>TemplateData</code>, et un fichier <code>index.html</code>.</li><li>Poussez les changements dans le dossier <code>docs</code> sur votre dépôt GitHub.</li></ol><h2 id="etape-3-mettre-en-ligne-sur-github-pages" tabindex="-1">Étape 3 : Mettre en ligne sur GitHub Pages <a class="header-anchor" href="#etape-3-mettre-en-ligne-sur-github-pages" aria-label="Permalink to “Étape 3 : Mettre en ligne sur GitHub Pages”">​</a></h2><ol><li>Ouvrez votre dépôt GitHub dans votre navigateur.</li><li>Allez dans les <strong>Settings</strong> (Paramètres) de votre dépôt.</li><li>Dans le menu de gauche, cliquez sur <strong>Pages</strong>.</li><li>Sous <strong>Source</strong>, sélectionnez la branche <code>main</code> (ou la branche que vous utilisez) et le dossier <code>/docs</code>.</li><li>Cliquez sur <strong>Save</strong>.</li><li>Attendez quelques minutes que GitHub génère votre site. Vous verrez une URL où votre projet est hébergé, généralement sous la forme <code>https://votre-nom-utilisateur.github.io/votre-repo/</code>.</li></ol><h2 id="etape-4-acceder-a-votre-projet-en-ligne" tabindex="-1">Étape 4 : Accéder à votre projet en ligne <a class="header-anchor" href="#etape-4-acceder-a-votre-projet-en-ligne" aria-label="Permalink to “Étape 4 : Accéder à votre projet en ligne”">​</a></h2><ol><li>Ouvrez un navigateur web et accédez à l&#39;URL fournie par GitHub Pages.</li><li>Votre projet Unity compilé devrait se charger et être prêt à être utilisé en ligne.</li></ol>',9)])])}const h=t(s,[["render",o]]);export{g as __pageData,h as default};
